/** Garantiza que la partida esté en memoria (p. ej. tras cerrar la app). */
public void asegurar(Runnable listo, Runnable sinPartida) {
    if (cargada()) {
        listo.run();
        return;
    }
    long id = prefs.usuarioId();
    if (id <= 0) {
        sinPartida.run();
        return;
    }
    repo.cargar(id, p -> {
        if (p == null) {
            sinPartida.run();
        } else {
            establecer(id, p);
            tick();
            listo.run();
        }
    });
}

